from __future__ import annotations

from typing import Any, Dict, Optional


class SalesforceAPIError(Exception):
    """Base exception for all Salesforce errors.

    Explicit attributes make later retry classifier and DLQ storage simple:
      ``status_code`` -> HTTP status (None for transport errors)
      ``error_code`` -> short alphanumeric class, e.g. INVALID_CLIENT, INVALID_SESSION_ID
      ``retryable`` -> direct hint to the future retry classifier (None means "use classifier")
      ``response_payload`` -> dict returned by Salesforce for structured introspection
    """

    def __init__(
        self,
        message: str,
        *,
        status_code: Optional[int] = None,
        error_code: Optional[str] = None,
        retryable: Optional[bool] = None,
        response_payload: Optional[Dict[str, Any]] = None,
    ) -> None:
        super().__init__(message)
        self.message = message
        self.status_code = status_code
        self.error_code = error_code
        self.retryable = retryable
        self.response_payload = response_payload or {}

    def __str__(self) -> str:  # pragma: no cover - trivial
        parts = [self.message]
        if self.status_code is not None:
            parts.append(f"status_code={self.status_code}")
        if self.error_code:
            parts.append(f"error_code={self.error_code}")
        if self.retryable is not None:
            parts.append(f"retryable={self.retryable}")
        return " | ".join(parts)


class SalesforceInvalidCredentialsError(SalesforceAPIError):
    """Token grant failed because credentials are wrong / expired / revoked."""

    def __init__(self, message: str, **kwargs: Any) -> None:
        super().__init__(
            message,
            status_code=kwargs.pop("status_code", 401),
            error_code=kwargs.pop("error_code", "INVALID_CREDENTIALS"),
            retryable=False,
            **kwargs,
        )


class SalesforceAuthenticationError(SalesforceAPIError):
    """Auth endpoint returned an error not classified as invalid credentials."""

    def __init__(self, message: str, **kwargs: Any) -> None:
        super().__init__(
            message,
            status_code=kwargs.pop("status_code", 400),
            error_code=kwargs.pop("error_code", "AUTH_ERROR"),
            retryable=kwargs.pop("retryable", None),
            **kwargs,
        )


class SalesforceUnauthorizedError(SalesforceAPIError):
    """401 / INVALID_SESSION_ID etc. from API calls (not the token grant)."""

    def __init__(self, message: str, **kwargs: Any) -> None:
        super().__init__(
            message,
            status_code=kwargs.pop("status_code", 401),
            error_code=kwargs.pop("error_code", "UNAUTHORIZED"),
            retryable=False,
            **kwargs,
        )


class SalesforceForbiddenError(SalesforceAPIError):
    """403: authenticated but insufficient permissions / connected app blocked."""

    def __init__(self, message: str, **kwargs: Any) -> None:
        super().__init__(
            message,
            status_code=kwargs.pop("status_code", 403),
            error_code=kwargs.pop("error_code", "FORBIDDEN"),
            retryable=False,
            **kwargs,
        )


class SalesforceInvalidRequestError(SalesforceAPIError):
    """400: malformed SOQL, bad request body, invalid enum, etc."""

    def __init__(self, message: str, **kwargs: Any) -> None:
        super().__init__(
            message,
            status_code=kwargs.pop("status_code", 400),
            error_code=kwargs.pop("error_code", "INVALID_REQUEST"),
            retryable=False,
            **kwargs,
        )


class SalesforceNotFoundError(SalesforceAPIError):
    """404: invalid job id, deleted object, wrong instance url."""

    def __init__(self, message: str, **kwargs: Any) -> None:
        super().__init__(
            message,
            status_code=kwargs.pop("status_code", 404),
            error_code=kwargs.pop("error_code", "NOT_FOUND"),
            retryable=False,
            **kwargs,
        )


class SalesforceServerError(SalesforceAPIError):
    """5xx: transient on Salesforce side, eligible for retry."""

    def __init__(self, message: str, **kwargs: Any) -> None:
        super().__init__(
            message,
            status_code=kwargs.pop("status_code", None),
            error_code=kwargs.pop("error_code", "SERVER_ERROR"),
            retryable=True,
            **kwargs,
        )


class SalesforceTimeoutError(SalesforceAPIError):
    """ConnectTimeout / ReadTimeout / general transport timeout / network blip."""

    def __init__(self, message: str, **kwargs: Any) -> None:
        super().__init__(
            message,
            status_code=kwargs.pop("status_code", None),
            error_code=kwargs.pop("error_code", "TIMEOUT"),
            retryable=True,
            **kwargs,
        )


def classify_http_error(status_code: int, payload: Optional[Dict[str, Any]], message: str) -> SalesforceAPIError:
    """Map a Salesforce HTTP status + payload onto a structured exception.

    Uses Salesforce's standard ``[].errorCode`` list payload shape plus HTTP
    status.  Does not log anything; callers are responsible for scrubbing logs.
    """
    error_code: Optional[str] = None
    if isinstance(payload, list) and len(payload) >= 1 and isinstance(payload[0], dict):
        error_code = payload[0].get("errorCode") or payload[0].get("code")
    elif isinstance(payload, dict):
        error_code = (
            payload.get("errorCode")
            or payload.get("code")
            or payload.get("error")
        )

    if 500 <= status_code < 600:
        return SalesforceServerError(message, status_code=status_code, error_code=error_code, response_payload=payload or {})
    if status_code == 404:
        return SalesforceNotFoundError(message, error_code=error_code, response_payload=payload or {})
    if status_code == 403:
        return SalesforceForbiddenError(message, error_code=error_code, response_payload=payload or {})
    if status_code == 401:
        if error_code == "INVALID_SESSION_ID":
            return SalesforceUnauthorizedError(message, error_code=error_code, response_payload=payload or {})
        return SalesforceUnauthorizedError(message, error_code=error_code, response_payload=payload or {})
    if status_code == 400:
        return SalesforceInvalidRequestError(message, error_code=error_code, response_payload=payload or {})
    if status_code == 429:
        return SalesforceServerError(
            message,
            status_code=429,
            error_code=error_code or "TOO_MANY_REQUESTS",
            response_payload=payload or {},
        )
    return SalesforceAPIError(
        message,
        status_code=status_code,
        error_code=error_code or f"HTTP_{status_code}",
        retryable=None,
        response_payload=payload or {},
    )

from __future__ import annotations

import csv
import json
import re
import shutil
from pathlib import Path
from typing import Any, Dict, Iterator, Optional

from src.app.core.config import get_settings
from src.app.core.logging_setup import get_logger

log = get_logger(__name__)


class BatchFileService:
    """CSV I/O for extracted Bulk API results. Full behavior Phase 2."""

    def __init__(self, data_root: Optional[str] = None) -> None:
        settings = get_settings()
        self.data_root = Path(data_root or settings.DATA_ROOT_DIR).resolve()

    def scan_dir(self, scan_id: str, stage: str = "extracted") -> Path:
        self._validate_component(scan_id)
        self._validate_component(stage)
        directory = self.data_root / scan_id / stage
        directory.mkdir(parents=True, exist_ok=True)
        return directory

    @staticmethod
    def _validate_component(value: str) -> None:
        if not value or not re.fullmatch(r"[A-Za-z0-9_.-]+", value):
            raise ValueError("path component contains invalid characters")

    def _safe_file(self, scan_id: str, object_name: str) -> Path:
        self._validate_component(scan_id)
        self._validate_component(object_name)
        path = (self.scan_dir(scan_id) / f"{object_name}.csv").resolve()
        root = self.data_root.resolve()
        if root not in path.parents:
            raise ValueError("result path escapes data root")
        return path

    def save_results_to_disk(
        self, scan_id: str, object_name: str, csv_stream: Iterator[str]
    ) -> Dict[str, Any]:
        path = self._safe_file(scan_id, object_name)
        rows = 0
        size = 0
        with path.open("wb") as output:
            for chunk in csv_stream:
                data = chunk.encode("utf-8") if isinstance(chunk, str) else bytes(chunk)
                output.write(data)
                size += len(data)
        try:
            with path.open("r", encoding="utf-8-sig", newline="") as source:
                rows = max(0, sum(1 for _ in csv.DictReader(source)))
        except (UnicodeError, csv.Error) as exc:
            path.unlink(missing_ok=True)
            raise ValueError(f"malformed CSV for {object_name}: {exc}") from exc
        return {"object_name": object_name, "path": str(path), "file_size": size, "record_count": rows}

    def read_csv_file(
        self,
        path: str,
        page: Optional[int] = None,
        page_size: Optional[int] = None,
    ) -> List[Dict[str, Any]]:
        file_path = Path(path).resolve()
        if not file_path.is_file() or self.data_root.resolve() not in file_path.parents:
            raise ValueError("CSV path is outside the configured data root")
        start = 0 if page is None else max(0, (page - 1) * (page_size or 0))
        limit = None if page_size is None else max(0, page_size)
        records = []
        with file_path.open("r", encoding="utf-8-sig", newline="") as source:
            reader = csv.DictReader(source)
            for index, row in enumerate(reader):
                if index < start:
                    continue
                if limit is not None and len(records) >= limit:
                    break
                records.append(dict(row))
        return records

    def get_file_info(self, scan_id: str) -> Dict[str, Any]:
        directory = self.scan_dir(scan_id)
        result: Dict[str, Any] = {"files": [], "total_records": 0}
        for path in sorted(directory.glob("*.csv")):
            info = {"object_name": path.stem, "path": str(path), "file_size": path.stat().st_size}
            with path.open("r", encoding="utf-8-sig", newline="") as source:
                info["record_count"] = max(0, sum(1 for _ in csv.DictReader(source)))
            result["files"].append(info)
            result["total_records"] += info["record_count"]
        return result

    def infer_schema(self, path: str) -> Dict[str, Any]:
        records = self.read_csv_file(path, page=1, page_size=100)
        fields = {}
        for record in records:
            for key, value in record.items():
                if value in (None, ""):
                    continue
                current = fields.get(key, "string")
                if current == "string":
                    if value.lower() in {"true", "false"}:
                        fields[key] = "boolean"
                    else:
                        try:
                            int(value)
                            fields[key] = "integer"
                        except ValueError:
                            try:
                                float(value)
                                fields[key] = "number"
                            except ValueError:
                                fields[key] = "string"
        return fields

    def cleanup_extracted_files(self, scan_id: str) -> None:
        self._validate_component(scan_id)
        directory = (self.data_root / scan_id / "extracted").resolve()
        if self.data_root.resolve() not in directory.parents:
            raise ValueError("cleanup path escapes data root")
        if directory.exists():
            shutil.rmtree(directory)

from __future__ import annotations

import json
from pathlib import Path
from typing import Any, Dict, List

from src.app.core.logging_setup import get_logger

log = get_logger(__name__)


class BaseNormalizer:
    object_name: str = "base"
    output_tables: List[str] = []

    def normalize(self, records: List[Dict[str, Any]]) -> Dict[str, List[Dict[str, Any]]]:
        raise NotImplementedError

    @staticmethod
    def safe_get(record: Dict[str, Any], key: str, default: Any = None) -> Any:
        if not isinstance(record, dict):
            return default
        value = record.get(key, default)
        if isinstance(value, str):
            stripped = value.strip()
            return stripped if stripped else default
        return value

    def get_statistics(self, tables: Dict[str, List[Dict[str, Any]]]) -> Dict[str, Any]:
        return {name: len(rows) for name, rows in tables.items()}

    def save_to_files(self, tables: Dict[str, List[Dict[str, Any]]], directory: str, output_format: str = "parquet") -> Dict[str, str]:
        output_dir = Path(directory)
        output_dir.mkdir(parents=True, exist_ok=True)
        if output_format not in {"json", "parquet"}:
            raise ValueError("output_format must be json or parquet")
        paths = {}
        for table_name, rows in tables.items():
            path = output_dir / f"{table_name}.{output_format}"
            if output_format == "json":
                path.write_text(json.dumps(rows, default=str), encoding="utf-8")
            else:
                import pandas as pd
                pd.DataFrame(rows).to_parquet(path, index=False)
            paths[table_name] = str(path)
        return paths

    def _row(self, record: Dict[str, Any], keys: List[str]) -> Dict[str, Any]:
        return {key.lower(): self.safe_get(record, key) for key in keys}

    def _children(self, record: Dict[str, Any], relationship: str) -> List[Dict[str, Any]]:
        value = record.get(relationship) or record.get(relationship.lower()) or []
        if isinstance(value, dict):
            value = value.get("records", [])
        return value if isinstance(value, list) else []


class AccountNormalizer(BaseNormalizer):
    object_name = "Account"
    output_tables = ["accounts", "account_addresses", "account_teams"]

    def normalize(self, records):
        accounts, addresses, teams = [], [], []
        for record in records:
            account = self._row(record, ["Id", "Name", "AccountNumber", "Type", "Industry", "Phone", "Website", "OwnerId", "ParentId", "CreatedDate", "LastModifiedDate"])
            accounts.append(account)
            for prefix, kind in (("Billing", "billing"), ("Shipping", "shipping")):
                address = self._row(record, [f"{prefix}Street", f"{prefix}City", f"{prefix}State", f"{prefix}PostalCode", f"{prefix}Country"])
                if any(value is not None for value in address.values()):
                    addresses.append({"account_id": account["id"], "address_type": kind, **address})
            if account.get("ownerid"):
                teams.append({"account_id": account["id"], "user_id": account["ownerid"], "role": "owner"})
        return {"accounts": accounts, "account_addresses": addresses, "account_teams": teams}


class ContactNormalizer(BaseNormalizer):
    object_name = "Contact"
    output_tables = ["contacts", "contact_roles"]

    def normalize(self, records):
        contacts, roles = [], []
        for record in records:
            contact = self._row(record, ["Id", "AccountId", "FirstName", "LastName", "Name", "Email", "Phone", "MobilePhone", "Title", "Department", "OwnerId", "CreatedDate", "LastModifiedDate"])
            contacts.append(contact)
            if contact.get("accountid"):
                roles.append({"contact_id": contact["id"], "account_id": contact["accountid"], "role": "contact"})
        return {"contacts": contacts, "contact_roles": roles}


class OpportunityNormalizer(BaseNormalizer):
    object_name = "Opportunity"
    output_tables = [
        "opportunities",
        "opportunity_line_items",
        "opportunity_contact_roles",
    ]

    def normalize(self, records):
        opportunities, line_items, roles = [], [], []
        for record in records:
            opportunity = self._row(record, ["Id", "AccountId", "Name", "StageName", "Amount", "CloseDate", "Probability", "Type", "LeadSource", "OwnerId", "CreatedDate", "LastModifiedDate"])
            opportunities.append(opportunity)
            for item in self._children(record, "OpportunityLineItems"):
                line_items.append({"opportunity_id": opportunity["id"], **self._row(item, ["Id", "Product2Id", "ProductCode", "Name", "Quantity", "UnitPrice", "TotalPrice", "ServiceDate"])})
            for role in self._children(record, "OpportunityContactRoles"):
                roles.append({"opportunity_id": opportunity["id"], **self._row(role, ["ContactId", "Role", "IsPrimary"])})
        return {"opportunities": opportunities, "opportunity_line_items": line_items, "opportunity_contact_roles": roles}


class LeadNormalizer(BaseNormalizer):
    object_name = "Lead"
    output_tables = ["leads"]

    def normalize(self, records):
        return {"leads": [self._row(record, ["Id", "FirstName", "LastName", "Name", "Company", "Title", "Email", "Phone", "MobilePhone", "Status", "LeadSource", "Industry", "Street", "City", "State", "PostalCode", "Country", "OwnerId", "CreatedDate", "LastModifiedDate"]) for record in records]}


class CaseNormalizer(BaseNormalizer):
    object_name = "Case"
    output_tables = ["cases", "case_comments"]

    def normalize(self, records):
        cases, comments = [], []
        for record in records:
            case = self._row(record, ["Id", "AccountId", "ContactId", "CaseNumber", "Subject", "Description", "Status", "Priority", "Origin", "Type", "Reason", "OwnerId", "CreatedDate", "LastModifiedDate"])
            cases.append(case)
            for comment in self._children(record, "CaseComments"):
                comments.append({"case_id": case["id"], **self._row(comment, ["Id", "CommentBody", "CreatedDate", "CreatedById"])})
        return {"cases": cases, "case_comments": comments}


class TaskEventNormalizer(BaseNormalizer):
    object_name = "TaskEvent"
    output_tables = ["tasks", "events"]

    def normalize(self, records):
        tasks, events = [], []
        for record in records:
            target = events if record.get("StartDateTime") or record.get("startdatetime") else tasks
            target.append(self._row(record, ["Id", "WhoId", "WhatId", "OwnerId", "Subject", "Description", "Status", "Priority", "ActivityDate", "CompletedDateTime", "StartDateTime", "EndDateTime", "IsAllDayEvent", "Location", "CreatedDate", "LastModifiedDate"]))
        return {"tasks": tasks, "events": events}


class CampaignNormalizer(BaseNormalizer):
    object_name = "Campaign"
    output_tables = ["campaigns", "campaign_members"]

    def normalize(self, records):
        campaigns, members = [], []
        for record in records:
            campaign = self._row(record, ["Id", "Name", "Type", "Status", "StartDate", "EndDate", "IsActive", "OwnerId", "CreatedDate", "LastModifiedDate"])
            campaigns.append(campaign)
            for member in self._children(record, "CampaignMembers"):
                members.append({"campaign_id": campaign["id"], **self._row(member, ["Id", "LeadId", "ContactId", "Status", "HasResponded", "FirstRespondedDate"])})
        return {"campaigns": campaigns, "campaign_members": members}


class UserNormalizer(BaseNormalizer):
    object_name = "User"
    output_tables = ["users"]

    def normalize(self, records):
        return {"users": [self._row(record, ["Id", "Username", "FirstName", "LastName", "Name", "Email", "IsActive", "UserRoleId", "ProfileId", "Department", "Title", "CreatedDate", "LastModifiedDate"]) for record in records]}


NORMALIZER_REGISTRY: Dict[str, BaseNormalizer] = {
    "Account": AccountNormalizer(),
    "Contact": ContactNormalizer(),
    "Opportunity": OpportunityNormalizer(),
    "OpportunityLineItem": OpportunityNormalizer(),
    "Lead": LeadNormalizer(),
    "Case": CaseNormalizer(),
    "Task": TaskEventNormalizer(),
    "Event": TaskEventNormalizer(),
    "Campaign": CampaignNormalizer(),
    "User": UserNormalizer(),
}

SUPPORTED_OBJECTS_CATALOG: Dict[str, List[str]] = {
    n.object_name: n.output_tables for n in NORMALIZER_REGISTRY.values()
}

from __future__ import annotations

from typing import Any, Dict, List, Optional

from sqlalchemy.orm import Session

from src.app.core.logging_setup import get_logger
from src.app.services.job_service import JobService
from src.app.normalization.normalizers import NORMALIZER_REGISTRY
from src.app.services.batch_file_service import BatchFileService
from src.app.core.config import get_settings
from src.app.storage.minio_client import MinIOClient
from src.app.models import JobStatus

log = get_logger(__name__)


class NormalizationService:
    """Runs per-object normalizers and persists output tables. Implemented Phase 3."""

    def __init__(self, db: Session, job_service: JobService, *, file_service: Optional[BatchFileService] = None, minio_client: Optional[MinIOClient] = None) -> None:
        self.db = db
        self.job_service = job_service
        self.file_service = file_service or BatchFileService()
        settings = get_settings()
        self.minio_client = minio_client or MinIOClient(settings.MINIO_ENDPOINT, settings.MINIO_ACCESS_KEY, settings.MINIO_SECRET_KEY, settings.MINIO_BUCKET, settings.MINIO_SECURE)

    async def normalize_scan(
        self,
        scan_id: str,
        output_format: str = "parquet",
        save_to_disk: bool = True,
        upload_to_minio: bool = False,
        processing_date: Optional[str] = None,
    ) -> Dict[str, Any]:
        job = self.job_service.get_job(scan_id)
        if job is None:
            raise ValueError(f"scan {scan_id} not found")
        if job.status != JobStatus.EXTRACTED:
            raise ValueError("normalization requires an EXTRACTED scan")
        self.job_service.start_normalization(scan_id)
        output_dir = self.file_service.data_root / scan_id / "normalized"
        all_tables, paths = {}, {}
        try:
            for file_info in self.file_service.get_file_info(scan_id)["files"]:
                normalizer = NORMALIZER_REGISTRY.get(file_info["object_name"])
                if normalizer is None:
                    continue
                records = self.file_service.read_csv_file(file_info["path"])
                tables = normalizer.normalize(records)
                all_tables.update(tables)
                if save_to_disk or upload_to_minio:
                    paths.update(normalizer.save_to_files(tables, str(output_dir), output_format))
            stats = {name: len(rows) for name, rows in all_tables.items()}
            self.job_service.complete_normalization(scan_id, stats)
            if upload_to_minio:
                self.job_service.start_minio_upload(scan_id)
                date = processing_date or __import__("datetime").date.today().isoformat()
                keys = self.minio_client.upload_normalized_data(scan_id, job.organization_id or "unknown", date, paths)
                self.job_service.complete_minio_upload(scan_id, {str(index): key for index, key in enumerate(keys)})
                self.job_service.update_job_status(scan_id, JobStatus.COMPLETED)
            return {"scan_id": scan_id, "status": self.job_service.get_job(scan_id).status.value, "tables": stats, "paths": paths}
        except Exception as exc:
            self.job_service.fail_job(scan_id, exc)
            raise

    async def normalize_single_object(
        self, scan_id: str, object_name: str
    ) -> Dict[str, Any]:
        if object_name not in NORMALIZER_REGISTRY:
            raise ValueError(f"unsupported Salesforce object: {object_name}")
        job = self.job_service.get_job(scan_id)
        if job is None:
            raise ValueError(f"scan {scan_id} not found")
        info = next((item for item in self.file_service.get_file_info(scan_id)["files"] if item["object_name"] == object_name), None)
        if info is None:
            raise FileNotFoundError(f"no extracted file for {object_name}")
        tables = NORMALIZER_REGISTRY[object_name].normalize(self.file_service.read_csv_file(info["path"]))
        paths = NORMALIZER_REGISTRY[object_name].save_to_files(tables, str(self.file_service.data_root / scan_id / "normalized"))
        return {"scan_id": scan_id, "object_name": object_name, "tables": NORMALIZER_REGISTRY[object_name].get_statistics(tables), "paths": paths}

    def list_normalized_tables(self, scan_id: str) -> List[Dict[str, Any]]:
        directory = self.file_service.data_root / scan_id / "normalized"
        if not directory.exists():
            return []
        return [{"table_name": path.stem, "path": str(path), "file_size": path.stat().st_size} for path in sorted(directory.iterdir()) if path.is_file()]

    @staticmethod
    def supported_objects() -> List[Dict[str, Any]]:
        from src.app.normalization.normalizers import SUPPORTED_OBJECTS_CATALOG

        return [
            {"object_name": name, "output_tables": tables}
            for name, tables in SUPPORTED_OBJECTS_CATALOG.items()
        ]

from __future__ import annotations

from typing import Any, Dict, Optional

from fastapi import APIRouter, Depends, HTTPException, Query
from sqlalchemy.orm import Session

from src.app.core.utils import build_pagination_info
from src.app.db.session import get_db
from src.app.schemas.common import (
    PaginationInfo,
    ScanListResponse,
    ScanStartRequest,
    ScanStatisticsResponse,
    ScanStatusResponse,
)
from src.app.security.hmac import hmac_auth_required
from src.app.services.extraction_service import ExtractionService
from src.app.services.job_service import JobService

router = APIRouter(dependencies=[Depends(hmac_auth_required)])


def _extraction_service(db: Session = Depends(get_db)) -> ExtractionService:
    return ExtractionService(db, JobService(db))


@router.post("/start", status_code=202)
async def start_scan(
    request: ScanStartRequest,
    svc: ExtractionService = Depends(_extraction_service),
) -> Dict[str, Any]:
    return await svc.start_scan(request)


@router.get("/{scan_id}/status")
async def get_scan_status(
    scan_id: str,
    svc: ExtractionService = Depends(_extraction_service),
) -> ScanStatusResponse:
    status = svc.get_scan_status(scan_id)
    if status is None:
        raise HTTPException(status_code=404, detail=f"scan {scan_id} not found")
    return ScanStatusResponse(**status)


@router.post("/{scan_id}/cancel")
async def cancel_scan(
    scan_id: str,
    svc: ExtractionService = Depends(_extraction_service),
) -> Dict[str, Any]:
